window.OPUS_PAGES["009"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Asterism — Draw Your Own Sky</title>\n<meta name=\"description\" content=\"An antique celestial atlas you draw yourself: join procedurally generated stars with gold line work and each new constellation receives a mythic name, a Latin subtitle and an engraved label.\">\n<meta name=\"theme-color\" content=\"#060818\">\n<style>\n:root{\n  --night0:#060818;\n  --night1:#141a3d;\n  --gold:#e8c872;\n  --gold-hi:#f6e3a8;\n  --gold-line:rgba(232,200,114,.42);\n  --gold-faint:rgba(232,200,114,.16);\n  --vellum:#efe6cf;\n  --text:#e4dfcd;\n  --muted:#9ca2c6;\n  --glass:rgba(17,22,56,.58);\n  --serif:\"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"Book Antiqua\",P052,\"URW Palladio L\",Georgia,serif;\n  --panel-w:340px;\n  --edge:26px;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{\n  background:linear-gradient(180deg,var(--night0),var(--night1));\n  color:var(--text);\n  font-family:var(--serif);\n  overflow:hidden;\n  -webkit-font-smoothing:antialiased;\n}\n#app{position:fixed;inset:0;overflow:hidden}\n#sky{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:crosshair;outline:none}\n#sky.grabbing{cursor:grabbing}\n#sky.over-star{cursor:pointer}\n#sky:focus-visible{box-shadow:inset 0 0 0 2px var(--gold)}\n\n/* engraved frame */\n.frame{position:absolute;inset:12px;pointer-events:none;border:1px solid rgba(232,200,114,.34)}\n.frame::before{content:\"\";position:absolute;inset:5px;border:1px solid rgba(232,200,114,.14)}\n.frame::after{\n  content:\"\";position:absolute;left:18px;right:18px;top:-1px;height:7px;\n  background:repeating-linear-gradient(90deg,rgba(232,200,114,.45) 0 1px,transparent 1px 12px),\n             repeating-linear-gradient(90deg,rgba(232,200,114,.7) 0 1px,transparent 1px 60px);\n  background-size:auto 4px,auto 7px;background-repeat:repeat-x;\n  -webkit-mask:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);\n          mask:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);\n}\n.corner{position:absolute;width:30px;height:30px;color:var(--gold)}\n.corner.tl{left:-6px;top:-6px}\n.corner.tr{right:-6px;top:-6px;transform:scaleX(-1)}\n.corner.bl{left:-6px;bottom:-6px;transform:scaleY(-1)}\n.corner.br{right:-6px;bottom:-6px;transform:scale(-1,-1)}\n\n/* masthead */\n.masthead{position:absolute;left:calc(var(--edge) + 20px);top:calc(var(--edge) + 14px);pointer-events:none;max-width:min(560px,60vw)}\n.kicker{margin:0 0 10px;font-size:11px;letter-spacing:.42em;text-transform:uppercase;color:var(--gold);opacity:.9}\n.masthead h1{\n  margin:0;font-weight:400;font-size:clamp(34px,4.1vw,60px);line-height:1;letter-spacing:.34em;\n  color:var(--vellum);text-shadow:0 0 22px rgba(232,200,114,.28),0 1px 0 rgba(0,0,0,.6);\n  margin-right:-.34em;\n}\n.rule{display:block;width:min(360px,70%);height:14px;margin:12px 0 10px;color:var(--gold)}\n.masthead .sub{margin:0;font-style:italic;font-size:clamp(14px,1.2vw,17px);color:#c9c6d8;letter-spacing:.02em;line-height:1.45}\n.masthead .sub b{font-weight:400;color:var(--gold-hi)}\n\n/* stage ui: hint + toolbar */\n.stage-ui{position:absolute;left:230px;right:calc(var(--panel-w) + 40px);bottom:calc(var(--edge) + 16px);display:flex;flex-direction:column;align-items:center;gap:12px;pointer-events:none}\n.hint{\n  pointer-events:none;margin:0;font-style:italic;font-size:15px;color:#d8d3c0;letter-spacing:.02em;\n  padding:6px 18px;text-shadow:0 1px 8px rgba(0,0,0,.9);transition:opacity .4s;\n}\n.hint .k{font-style:normal;font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--gold);margin-right:10px}\n.toolbar{pointer-events:auto;display:flex;flex-wrap:wrap;justify-content:center;gap:8px;padding:8px;background:rgba(7,10,30,.5);border:1px solid rgba(232,200,114,.22);box-shadow:0 18px 40px -18px rgba(0,0,0,.9)}\n.tool{\n  appearance:none;display:inline-flex;align-items:center;gap:8px;min-height:38px;\n  padding:9px 15px;border:1px solid rgba(232,200,114,.36);border-radius:1px;\n  background:linear-gradient(180deg,rgba(26,32,74,.75),rgba(10,13,36,.75));\n  color:var(--vellum);font:inherit;font-size:11.5px;letter-spacing:.24em;text-transform:uppercase;cursor:pointer;\n  box-shadow:inset 0 0 0 3px rgba(6,8,24,.55),inset 0 0 0 4px rgba(232,200,114,.1);\n  transition:background .25s,border-color .25s,color .25s,transform .15s;\n}\n.tool svg{width:15px;height:15px;flex:none;color:var(--gold)}\n.tool:hover{border-color:var(--gold);background:linear-gradient(180deg,rgba(40,46,98,.85),rgba(14,18,48,.85))}\n.tool:active{transform:translateY(1px)}\n.tool:focus-visible,.entry button:focus-visible,.panel-toggle:focus-visible{outline:2px solid var(--gold-hi);outline-offset:3px}\n.tool.primary{background:linear-gradient(180deg,#f3dc98,#d4ad52);color:#1a1606;border-color:#f6e3a8;box-shadow:inset 0 0 0 3px rgba(255,248,220,.35),0 0 24px -4px rgba(232,200,114,.55)}\n.tool.primary svg{color:#2a2208}\n.tool.primary:hover{background:linear-gradient(180deg,#fae7ae,#dfb85c)}\n.tool[aria-pressed=\"true\"]{border-color:var(--gold);color:var(--gold-hi);background:linear-gradient(180deg,rgba(66,58,30,.8),rgba(28,24,12,.8))}\n.tool.armed{border-color:#e98a6c;color:#ffd0c0}\n.tool.armed svg{color:#e98a6c}\n\n/* readout */\n.readout{position:absolute;left:calc(var(--edge) + 20px);bottom:calc(var(--edge) + 18px);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(232,200,114,.78);pointer-events:none;line-height:1.9}\n.readout em{font-style:italic;text-transform:none;letter-spacing:.04em;color:#b9b6cc;font-size:12.5px}\n.readout .val{color:var(--vellum);font-variant-numeric:tabular-nums}\n\n/* panel */\n.panel{\n  position:absolute;top:calc(var(--edge) + 6px);right:calc(var(--edge) + 6px);bottom:calc(var(--edge) + 6px);width:var(--panel-w);\n  display:flex;flex-direction:column;\n  background:linear-gradient(180deg,rgba(24,30,72,.6),rgba(9,12,34,.66));\n  -webkit-backdrop-filter:blur(14px) saturate(1.15);backdrop-filter:blur(14px) saturate(1.15);\n  border:1px solid rgba(232,200,114,.3);box-shadow:0 30px 60px -30px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,240,200,.08);\n  transition:transform .55s cubic-bezier(.2,.8,.2,1);z-index:3;\n}\n.panel::before{content:\"\";position:absolute;inset:6px;border:1px solid rgba(232,200,114,.1);pointer-events:none}\n.panel-toggle{display:none}\n.panel-head{padding:26px 26px 14px;text-align:center;border-bottom:1px solid rgba(232,200,114,.16)}\n.panel-head .kick{margin:0 0 6px;font-size:10px;letter-spacing:.5em;text-transform:uppercase;color:var(--gold);padding-left:.5em}\n.panel-head h2{margin:0;font-weight:400;font-size:21px;letter-spacing:.26em;text-transform:uppercase;color:var(--vellum);padding-left:.26em}\n.panel-head p.lat{margin:6px 0 0;font-style:italic;color:var(--muted);font-size:14px}\n.orn{display:block;margin:12px auto 0;width:150px;height:10px;color:var(--gold)}\n.list-wrap{flex:1;overflow:auto;padding:10px 14px 6px;scrollbar-width:thin;scrollbar-color:rgba(232,200,114,.35) transparent}\n#list{list-style:none;margin:0;padding:0}\n.entry{position:relative;display:flex;align-items:stretch;border-bottom:1px solid rgba(232,200,114,.1);transition:background .3s}\n.entry.hot{background:linear-gradient(90deg,rgba(232,200,114,.12),rgba(232,200,114,0))}\n.entry.fresh{animation:inked 1.4s ease-out}\n@keyframes inked{from{background:rgba(232,200,114,.28)}to{background:transparent}}\n.entry-main{flex:1;display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:6px;text-align:left;background:none;border:0;color:inherit;font:inherit;padding:12px 6px 12px 4px;cursor:pointer;min-width:0}\n.entry .num{font-size:13px;letter-spacing:.12em;color:var(--gold);text-align:center;font-variant:small-caps}\n.entry .names{display:flex;flex-direction:column;min-width:0}\n.entry .nm{font-size:12.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--vellum);line-height:1.35}\n.entry .lat{font-style:italic;font-size:13.5px;color:var(--muted);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.entry .meta{font-size:11px;color:rgba(232,200,114,.7);letter-spacing:.08em;white-space:nowrap;padding-left:4px}\n.entry-del{flex:none;width:34px;background:none;border:0;color:rgba(232,200,114,.45);cursor:pointer;display:grid;place-items:center;transition:color .2s}\n.entry-del:hover{color:#ff9f86}\n.entry-del svg{width:12px;height:12px}\n.empty{margin:28px 16px;text-align:center;font-style:italic;color:var(--muted);font-size:15px;line-height:1.6}\n.empty[hidden]{display:none}\n.panel-foot{padding:14px 22px 20px;border-top:1px solid rgba(232,200,114,.16);font-size:12.5px;line-height:1.6;color:#a9aac2}\n.panel-foot p{margin:0 0 8px}\n.panel-foot p:last-child{margin:0}\n.keys{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:rgba(232,200,114,.72)}\nkbd{font-family:inherit;border:1px solid rgba(232,200,114,.35);padding:0 5px;border-radius:2px;color:var(--vellum);font-size:10px}\n\n/* toast */\n.toast{\n  position:absolute;left:50%;top:calc(var(--edge) + 22px);transform:translate(-50%,-14px);opacity:0;pointer-events:none;\n  padding:12px 24px;background:rgba(9,12,34,.82);border:1px solid rgba(232,200,114,.45);text-align:center;\n  transition:opacity .5s,transform .5s cubic-bezier(.2,.8,.2,1);z-index:4;max-width:min(520px,calc(100vw - 40px));\n  margin-left:calc(var(--panel-w) / -2 - 15px);\n}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.toast .t1{display:block;font-size:12.5px;letter-spacing:.26em;text-transform:uppercase;color:var(--gold-hi)}\n.toast .t2{display:block;font-style:italic;color:#cfcbe0;font-size:14px;margin-top:3px}\n\n.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n\n@media (max-width:1240px){\n  .readout{display:none}\n  .stage-ui{left:0}\n}\n@media (max-width:980px){\n  :root{--panel-w:300px}\n  .tool{padding:9px 11px;letter-spacing:.16em}\n}\n@media (max-width:760px){\n  :root{--edge:10px}\n  .frame{inset:6px}\n  .frame::after{display:none}\n  .masthead{left:24px;top:22px;max-width:calc(100vw - 150px)}\n  .kicker{font-size:9px;letter-spacing:.3em;margin-bottom:6px}\n  .kicker .yr{display:none}\n  .masthead h1{font-size:30px;letter-spacing:.24em;margin-right:-.24em}\n  .rule{margin:8px 0 6px;width:200px}\n  .masthead .sub{font-size:13px;max-width:240px}\n  .readout{display:none}\n  .stage-ui{right:0;left:0;bottom:16px;padding:0 14px;gap:8px}\n  .hint{font-size:13.5px;text-align:center;padding:4px 8px}\n  .toolbar{display:grid;grid-template-columns:repeat(3,1fr);width:100%;max-width:420px;gap:6px;padding:6px}\n  .tool{justify-content:center;padding:8px 6px;font-size:10px;letter-spacing:.14em;gap:6px;min-height:40px}\n  .tool svg{width:13px;height:13px}\n  .panel{top:12px;right:12px;bottom:auto;left:12px;width:auto;max-height:calc(100% - 190px);transform:translateY(calc(-100% - 30px))}\n  .panel.open{transform:none}\n  .panel-toggle{\n    display:inline-flex;align-items:center;gap:8px;position:absolute;right:18px;top:22px;z-index:5;\n    padding:9px 12px;background:rgba(9,12,34,.72);border:1px solid rgba(232,200,114,.45);color:var(--vellum);\n    font:inherit;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;\n    -webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);\n  }\n  .panel-toggle .count{display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:50%;background:var(--gold);color:#1a1606;font-size:11px;letter-spacing:0}\n  .panel-toggle[aria-expanded=\"true\"]{background:rgba(66,58,30,.85)}\n  .panel-head{padding:18px 18px 10px}\n  .panel-foot{display:none}\n  .toast{margin-left:0;top:auto;bottom:170px}\n}\n@media (prefers-reduced-motion:reduce){\n  .panel,.toast,.entry,.tool{transition:none}\n  .entry.fresh{animation:none}\n}\n</style>\n</head>\n<body>\n<main id=\"app\">\n  <canvas id=\"sky\" tabindex=\"0\" role=\"application\" aria-roledescription=\"star chart\" aria-label=\"Star chart. Click one star, then another, to draw gold lines between them. Close the figure or press Name it to name your constellation. Drag to rotate the sky.\" aria-describedby=\"keyhelp\"></canvas>\n\n  <div class=\"frame\" aria-hidden=\"true\">\n    <svg class=\"corner tl\" viewBox=\"0 0 30 30\"><path d=\"M6 29V6h23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/><path d=\"M10 29V10h19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\".6\" opacity=\".6\"/><path d=\"M6 6l6 6\" stroke=\"currentColor\" stroke-width=\".8\"/><circle cx=\"13.5\" cy=\"13.5\" r=\"2\" fill=\"currentColor\"/><path d=\"M13.5 9.2l.9 3.4 3.4.9-3.4.9-.9 3.4-.9-3.4-3.4-.9 3.4-.9z\" fill=\"currentColor\" opacity=\".7\"/></svg>\n    <svg class=\"corner tr\" viewBox=\"0 0 30 30\"><path d=\"M6 29V6h23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/><path d=\"M10 29V10h19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\".6\" opacity=\".6\"/><path d=\"M6 6l6 6\" stroke=\"currentColor\" stroke-width=\".8\"/><circle cx=\"13.5\" cy=\"13.5\" r=\"2\" fill=\"currentColor\"/></svg>\n    <svg class=\"corner bl\" viewBox=\"0 0 30 30\"><path d=\"M6 29V6h23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/><path d=\"M10 29V10h19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\".6\" opacity=\".6\"/><path d=\"M6 6l6 6\" stroke=\"currentColor\" stroke-width=\".8\"/><circle cx=\"13.5\" cy=\"13.5\" r=\"2\" fill=\"currentColor\"/></svg>\n    <svg class=\"corner br\" viewBox=\"0 0 30 30\"><path d=\"M6 29V6h23\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/><path d=\"M10 29V10h19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\".6\" opacity=\".6\"/><path d=\"M6 6l6 6\" stroke=\"currentColor\" stroke-width=\".8\"/><circle cx=\"13.5\" cy=\"13.5\" r=\"2\" fill=\"currentColor\"/></svg>\n  </div>\n\n  <header class=\"masthead\">\n    <p class=\"kicker\">Tabula Caeli Nova<span class=\"yr\"> · Anno MMXXVI</span></p>\n    <h1>Asterism</h1>\n    <svg class=\"rule\" viewBox=\"0 0 360 14\" aria-hidden=\"true\" preserveAspectRatio=\"none\">\n      <path d=\"M0 7H150M210 7H360\" stroke=\"currentColor\" stroke-width=\".8\" opacity=\".7\"/>\n      <path d=\"M20 10H150M210 10H340\" stroke=\"currentColor\" stroke-width=\".4\" opacity=\".45\"/>\n      <path d=\"M180 0l2.2 4.8L187 7l-4.8 2.2L180 14l-2.2-4.8L173 7l4.8-2.2z\" fill=\"currentColor\"/>\n      <circle cx=\"160\" cy=\"7\" r=\"1.6\" fill=\"currentColor\"/><circle cx=\"200\" cy=\"7\" r=\"1.6\" fill=\"currentColor\"/>\n    </svg>\n    <p class=\"sub\"><em>Draw your own sky.</em> Join any stars you like — <b>close the figure</b> and the heavens will give it a name.</p>\n  </header>\n\n  <p class=\"readout\" aria-hidden=\"true\">\n    <span>Centrum tabulae</span><br>\n    <span>AR <span class=\"val\" id=\"roRA\">20ʰ 00ᵐ</span> &nbsp;·&nbsp; Decl. <span class=\"val\" id=\"roDec\">+40°</span></span><br>\n    <em id=\"roMode\">The sky turns slowly westward</em>\n  </p>\n\n  <div class=\"stage-ui\">\n    <p class=\"hint\" id=\"hint\" role=\"status\" aria-live=\"polite\"><span class=\"k\">Begin</span>Select a star to start a figure</p>\n    <nav class=\"toolbar\" aria-label=\"Chart tools\">\n      <button type=\"button\" class=\"tool primary\" id=\"btnName\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M8 .8l1.7 5.5L15.2 8l-5.5 1.7L8 15.2l-1.7-5.5L.8 8l5.5-1.7z\" fill=\"currentColor\"/></svg>Name it</button>\n      <button type=\"button\" class=\"tool\" id=\"btnUndo\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M5.5 3.5L2 7l3.5 3.5M2.4 7H10a4 4 0 010 8H7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>Undo</button>\n      <button type=\"button\" class=\"tool\" id=\"btnGrid\" aria-pressed=\"false\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"6.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.1\"/><ellipse cx=\"8\" cy=\"8\" rx=\"3\" ry=\"6.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/><path d=\"M1.6 5.6h12.8M1.6 10.4h12.8\" stroke=\"currentColor\" stroke-width=\"1\"/></svg>Grid</button>\n      <button type=\"button\" class=\"tool\" id=\"btnSpin\" aria-pressed=\"true\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M13.5 8A5.5 5.5 0 113 5.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><path d=\"M1.6 2.2L3 5.4l3.2-1.1\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><circle cx=\"8\" cy=\"8\" r=\"1.4\" fill=\"currentColor\"/></svg>Rotate</button>\n      <button type=\"button\" class=\"tool\" id=\"btnClear\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M3 3l10 10M13 3L3 13\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg><span id=\"clearLabel\">Clear sky</span></button>\n      <button type=\"button\" class=\"tool\" id=\"btnSave\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M8 1.5v8.5M4.5 6.8L8 10.3l3.5-3.5M2 12v2.5h12V12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>Save PNG</button>\n    </nav>\n  </div>\n\n  <button type=\"button\" class=\"panel-toggle\" id=\"panelToggle\" aria-expanded=\"false\" aria-controls=\"panel\">Catalogue <span class=\"count\" id=\"countBadge\">0</span></button>\n\n  <aside class=\"panel\" id=\"panel\" aria-label=\"Your constellations\">\n    <div class=\"panel-head\">\n      <p class=\"kick\">Catalogus</p>\n      <h2>Your Asterisms</h2>\n      <p class=\"lat\">Figurae a te delineatae</p>\n      <svg class=\"orn\" viewBox=\"0 0 150 10\" aria-hidden=\"true\"><path d=\"M0 5h62M88 5h62\" stroke=\"currentColor\" stroke-width=\".7\"/><path d=\"M75 0l1.6 3.4L80 5l-3.4 1.6L75 10l-1.6-3.4L70 5l3.4-1.6z\" fill=\"currentColor\"/><circle cx=\"66\" cy=\"5\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"84\" cy=\"5\" r=\"1.2\" fill=\"currentColor\"/></svg>\n    </div>\n    <div class=\"list-wrap\">\n      <ol id=\"list\"></ol>\n      <p class=\"empty\" id=\"empty\" hidden>The sky is unclaimed.<br>Link two or more stars and press <em>Name it</em> — or return to your first star to close the figure.</p>\n    </div>\n    <div class=\"panel-foot\">\n      <p>Hover an entry to light its figure; select it to turn the sky toward it. Your figures are kept in this browser.</p>\n      <p id=\"keyhelp\" class=\"keys\"><kbd>Enter</kbd> name · <kbd>Esc</kbd> cancel · <kbd>⌫</kbd> undo · <kbd>G</kbd> grid · <kbd>←→↑↓</kbd> turn</p>\n      <p><em>The stars are procedurally generated; the grid follows the true equatorial frame — right ascension, declination and the ecliptic at 23.4°.</em></p>\n    </div>\n  </aside>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"><span class=\"t1\" id=\"toastT1\"></span><span class=\"t2\" id=\"toastT2\"></span></div>\n</main>\n\n<script>\n(() => {\n'use strict';\nconst TAU = Math.PI * 2, D2R = Math.PI / 180;\nconst canvas = document.getElementById('sky');\nconst ctx = canvas.getContext('2d');\nconst reduceMQ = window.matchMedia('(prefers-reduced-motion: reduce)');\nlet reduced = reduceMQ.matches;\nconst SERIF = '\"Iowan Old Style\",\"Palatino Linotype\",Palatino,\"Book Antiqua\",P052,\"URW Palladio L\",Georgia,serif';\nconst GOLD = '#e8c872';\nconst STORE_KEY = 'asterism.sky.v1';\n\n/* ---------- seeded randomness: the same sky on every visit ---------- */\nfunction mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}\nconst rnd = mulberry32(90417);\nfunction gauss(){let u=0;while(u===0)u=rnd();return Math.sqrt(-2*Math.log(u))*Math.cos(TAU*rnd());}\nfunction radec(ra,dec){const c=Math.cos(dec);return [c*Math.cos(ra),c*Math.sin(ra),Math.sin(dec)];}\nfunction norm(v){const l=Math.hypot(v[0],v[1],v[2])||1;return [v[0]/l,v[1]/l,v[2]/l];}\nfunction dot(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}\nfunction cross(a,b){return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}\n\n/* ---------- galactic frame (real J2000 pole + centre) ---------- */\nconst GN = radec(192.8595*D2R, 27.1283*D2R);\nlet GA = radec(266.405*D2R, -28.936*D2R);\n{const d=dot(GA,GN);GA=norm([GA[0]-d*GN[0],GA[1]-d*GN[1],GA[2]-d*GN[2]]);}\nconst GB = cross(GN, GA);\nfunction galactic(l,b){const cb=Math.cos(b),sb=Math.sin(b),cl=Math.cos(l),sl=Math.sin(l);\n  return [cb*(cl*GA[0]+sl*GB[0])+sb*GN[0], cb*(cl*GA[1]+sl*GB[1])+sb*GN[1], cb*(cl*GA[2]+sl*GB[2])+sb*GN[2]];}\n\n/* ---------- stars ---------- */\nconst NS = 4300;\nconst SX=new Float32Array(NS),SY=new Float32Array(NS),SZ=new Float32Array(NS);\nconst MAG=new Float32Array(NS),RAD=new Float32Array(NS),ALP=new Float32Array(NS);\nconst PH=new Float32Array(NS),FQ=new Float32Array(NS),TB=new Uint8Array(NS);\nconst COL=new Array(NS);\nconst SPX=new Float32Array(NS),SPY=new Float32Array(NS),SVIS=new Uint8Array(NS);\nconst TSTOPS=[[0,[157,184,255]],[.3,[206,220,255]],[.5,[255,248,236]],[.72,[255,226,173]],[1,[255,179,102]]];\nfunction tcol(t){for(let k=1;k<TSTOPS.length;k++){if(t<=TSTOPS[k][0]){const a=TSTOPS[k-1],b=TSTOPS[k],f=(t-a[0])/(b[0]-a[0]);return [0,1,2].map(j=>Math.round(a[1][j]+(b[1][j]-a[1][j])*f));}}return TSTOPS[4][1];}\nfor(let i=0;i<NS;i++){\n  let v;\n  if(i<2900){const z=2*rnd()-1,ra=TAU*rnd(),c=Math.sqrt(1-z*z);v=[c*Math.cos(ra),c*Math.sin(ra),z];}\n  else{v=galactic(rnd()*TAU, gauss()*0.14);}\n  SX[i]=v[0];SY[i]=v[1];SZ[i]=v[2];\n  const m=Math.max(-1.3, 6.6+Math.log10(rnd()+1e-9)/0.44);\n  MAG[i]=m;\n  RAD[i]=0.55+Math.max(0,6.6-m)*0.42;\n  ALP[i]=Math.min(1,0.34+(6.6-m)*0.17);\n  PH[i]=rnd()*TAU; FQ[i]=0.0012+rnd()*0.0035;\n  let t=Math.min(1,Math.max(0,0.5+gauss()*0.21));\n  const c=tcol(t); COL[i]='rgb('+c[0]+','+c[1]+','+c[2]+')';\n  TB[i]=Math.min(4,Math.floor(t*5));\n}\n\n/* ---------- milky way: clustered noise particles along the galactic plane ---------- */\nconst NMW=2300, NDU=3600;\nconst MX=new Float32Array(NMW),MY=new Float32Array(NMW),MZ=new Float32Array(NMW),MS=new Float32Array(NMW),MA=new Float32Array(NMW),MT=new Uint8Array(NMW);\nconst DX=new Float32Array(NDU),DY=new Float32Array(NDU),DZ=new Float32Array(NDU),DA=new Float32Array(NDU);\nfunction mwSample(thick){\n  for(let guard=0;guard<60;guard++){\n    const l = rnd()<0.52 ? rnd()*TAU-Math.PI : gauss()*0.95;\n    const cf=(1+Math.cos(l))/2;\n    const b=gauss()*(thick+0.07*cf*cf);\n    const lane=0.014*Math.sin(l*2.3)+0.004;\n    if(Math.abs(l)<1.3 && Math.abs(b-lane)<0.026*(0.55+cf) && rnd()<0.82) continue;\n    const nz=0.5+0.5*Math.sin(l*11.7+Math.sin(l*3.1)*2)*Math.cos(b*37+l*5.3);\n    if(rnd()>0.3+0.7*nz) continue;\n    return {v:galactic(l,b),cf};\n  }\n  return {v:galactic(rnd()*TAU,0),cf:0.3};\n}\nfor(let i=0;i<NMW;i++){\n  const s=mwSample(0.075);\n  MX[i]=s.v[0];MY[i]=s.v[1];MZ[i]=s.v[2];\n  MS[i]=(12+rnd()*34)*(0.8+0.5*s.cf);\n  MA[i]=(0.028+0.05*rnd())*(0.5+0.65*s.cf);\n  const r=rnd(); MT[i]= r<0.2?2:(r<0.55?0:1);\n}\nfor(let i=0;i<NDU;i++){\n  const s=mwSample(0.055);\n  DX[i]=s.v[0];DY[i]=s.v[1];DZ[i]=s.v[2];\n  DA[i]=0.12+rnd()*0.4*(0.5+s.cf);\n}\n\n/* ---------- grid geometry (true RA/Dec + ecliptic) ---------- */\nconst PAR=[],MER=[];\nfor(let d=-75;d<=75;d+=15){const a=[];for(let r=0;r<=360;r+=2){const v=radec(r*D2R,d*D2R);a.push(v[0],v[1],v[2]);}PAR.push({dec:d,pts:new Float32Array(a)});}\nfor(let h=0;h<24;h++){const a=[];for(let d=-88;d<=88;d+=2){const v=radec(h*15*D2R,d*D2R);a.push(v[0],v[1],v[2]);}MER.push({h,pts:new Float32Array(a)});}\nconst EPS=23.4393*D2R, ECL=[];\nfor(let L=0;L<=360;L+=2){const l=L*D2R;ECL.push(Math.cos(l),Math.sin(l)*Math.cos(EPS),Math.sin(l)*Math.sin(EPS));}\nconst ECLP=new Float32Array(ECL);\n\n/* ---------- names ---------- */\nconst ADJ=[['Weeping','Lacrimans'],['Sleeping','Dormiens'],['Wandering','Errans'],['Burning','Ardens'],['Watchful','Vigilans'],['Singing','Cantans'],['Fleeing','Fugiens'],['Silent','Silens'],['Rising','Surgens'],['Falling','Cadens'],['Swimming','Natans'],['Dreaming','Somnians'],['Hidden','Latens'],['Returning','Rediens'],['Shining','Lucens'],['Laughing','Ridens'],['Waiting','Exspectans'],['Dancing','Saltans'],['Grieving','Maerens'],['Trembling','Tremens'],['Hunting','Venans'],['Listening','Auscultans'],['Drinking','Bibens'],['Flying','Volans']];\nconst NOUN=[['Heron','Ardea'],['Lantern','Lucerna'],['Stag','Cervus'],['Anchor','Ancora'],['Fox','Vulpes'],['Ferryman','Portitor'],['Mirror','Speculum'],['Sickle','Falx'],['Tower','Turris'],['Owl','Noctua'],['Tortoise','Testudo'],['Otter','Lutra'],['Boar','Aper'],['Sparrow','Passer'],['Chalice','Calix'],['Ladder','Scala'],['Weaver','Textor'],['Key','Clavis'],['Pilgrim','Peregrinus'],['Oar','Remus'],['Queen','Regina'],['Salmon','Salmo'],['Bell','Tintinnabulum'],['Dove','Columba'],['Whale','Balaena'],['Ship','Navis']];\nfunction makeName(){\n  const used=new Set(cons.map(c=>c.name));\n  for(let k=0;k<80;k++){\n    const a=ADJ[Math.floor(Math.random()*ADJ.length)],n=NOUN[Math.floor(Math.random()*NOUN.length)];\n    const name='The '+a[0]+' '+n[0];\n    if(!used.has(name)) return {name,latin:n[1]+' '+a[1]};\n  }\n  const a=ADJ[0],n=NOUN[Math.floor(Math.random()*NOUN.length)];\n  return {name:'The '+a[0]+' '+n[0]+' '+toRoman(cons.length+1),latin:n[1]+' '+a[1]};\n}\nfunction toRoman(n){const r=[[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];let s='';for(const [v,c] of r){while(n>=v){s+=c;n-=v;}}return s;}\n\n/* ---------- view + projection (stereographic, sky turning about the pole) ---------- */\nconst view={ra:304*D2R,dec:38*D2R,zoom:1,vra:0,vdec:0};\nlet cR=1,sR=0,cD=1,sD=0,SC=600,CX=0,CY=0,W=0,H=0,DPR=1,SZSCALE=1;\nlet PX=0,PY=0,PD=0;\nfunction setView(){cR=Math.cos(view.ra);sR=Math.sin(view.ra);cD=Math.cos(view.dec);sD=Math.sin(view.dec);}\nfunction proj(x,y,z){\n  const x1=x*cR+y*sR, y1=-x*sR+y*cR;\n  const d=x1*cD+z*sD;\n  if(d<-0.3) return false;\n  const up=-x1*sD+z*cD;\n  const k=SC*2/(1+d);\n  PX=CX-y1*k; PY=CY-up*k; PD=d;\n  return true;\n}\nfunction onScreen(m){return PX>-m&&PX<W+m&&PY>-m&&PY<H+m;}\n\n/* ---------- sprites ---------- */\nfunction blob(r,g,b,a){const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');const gr=x.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,'rgba('+r+','+g+','+b+','+a+')');gr.addColorStop(.35,'rgba('+r+','+g+','+b+','+(a*.45)+')');gr.addColorStop(1,'rgba('+r+','+g+','+b+',0)');x.fillStyle=gr;x.fillRect(0,0,64,64);return c;}\nconst MWSPR=[blob(150,176,255,1),blob(255,240,216,1),blob(255,196,150,1)];\nconst GLOW=[];for(let k=0;k<5;k++){const c=tcol((k+.5)/5);GLOW.push(blob(c[0],c[1],c[2],.9));}\nlet bgCanvas=null;\nfunction buildBackground(){\n  bgCanvas=document.createElement('canvas');bgCanvas.width=Math.max(1,Math.round(W*DPR));bgCanvas.height=Math.max(1,Math.round(H*DPR));\n  const b=bgCanvas.getContext('2d');b.setTransform(DPR,0,0,DPR,0,0);\n  const g=b.createLinearGradient(0,0,W*0.25,H);g.addColorStop(0,'#060818');g.addColorStop(1,'#141a3d');b.fillStyle=g;b.fillRect(0,0,W,H);\n  const r=b.createRadialGradient(W*0.42,H*0.45,0,W*0.42,H*0.45,Math.hypot(W,H)*0.62);\n  r.addColorStop(0,'rgba(40,52,120,0.22)');r.addColorStop(0.55,'rgba(10,14,40,0)');r.addColorStop(1,'rgba(2,3,10,0.65)');\n  b.fillStyle=r;b.fillRect(0,0,W,H);\n  // aquatint grain\n  const gr=mulberry32(77);const n=Math.round(W*H/90);\n  for(let i=0;i<n;i++){b.fillStyle=gr()<.5?'rgba(255,240,210,0.035)':'rgba(0,0,0,0.12)';b.fillRect(gr()*W,gr()*H,1,1);}\n}\n\n/* ---------- state ---------- */\nlet cons=[];        // {id,stars,edges,name,latin,made,born}\nlet chain=null;     // {stars,edges,last}\nlet listHover=null, canvasHover=null, hoverStar=-1;\nlet showGrid=false, spin=true;\nlet nextId=1;\nconst pointer={x:-999,y:-999,in:false};\nconst drag={down:false,moving:false,x0:0,y0:0,lx:0,ly:0,id:null,t:0,type:'mouse'};\nlet fly=null;\nlet meteor=null, nextMeteor=performance.now()+6000;\n\nfunction load(){\n  try{\n    const raw=localStorage.getItem(STORE_KEY);\n    if(raw===null) return false;\n    const d=JSON.parse(raw);\n    if(d&&Array.isArray(d.cons)){\n      cons=d.cons.filter(c=>c&&Array.isArray(c.edges)&&c.edges.length).map(c=>({id:nextId++,stars:c.stars.filter(s=>s>=0&&s<NS),edges:c.edges.filter(e=>e[0]<NS&&e[1]<NS),name:String(c.name||'Nameless'),latin:String(c.latin||''),made:c.made||'',born:-1e9}));\n      showGrid=!!d.grid;\n      return true;\n    }\n  }catch(e){}\n  return false;\n}\nfunction save(){\n  try{localStorage.setItem(STORE_KEY,JSON.stringify({cons:cons.map(c=>({stars:c.stars,edges:c.edges,name:c.name,latin:c.latin,made:c.made})),grid:showGrid}));}catch(e){}\n}\n\n/* ---------- layout ---------- */\nfunction resize(){\n  const r=canvas.getBoundingClientRect();\n  W=Math.max(1,r.width);H=Math.max(1,r.height);\n  DPR=Math.min(2,window.devicePixelRatio||1);\n  canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);\n  const mobile=W<760;\n  const panelW=mobile?0:(W<=980?300:340)+40;\n  CX=(W-panelW)/2; CY=H*(mobile?0.46:0.5);\n  const halfDiag=Math.hypot(W,H)/2;\n  const theta=(mobile?46:60)*D2R;\n  SC=halfDiag/(2*Math.tan(theta/2))*view.zoom;\n  SZSCALE=Math.max(0.55,Math.min(1.4,SC/700));\n  buildBackground();\n  labelCache.clear();\n}\n\n/* ---------- drawing helpers ---------- */\nconst labelCache=new Map();\nfunction spacedWidth(text,font,sp){\n  const key=font+'|'+sp+'|'+text;let w=labelCache.get(key);\n  if(w===undefined){ctx.font=font;w=[];let tot=0;for(const ch of text){const cw=ctx.measureText(ch).width;w.push(cw);tot+=cw+sp;}tot-=sp;w.total=tot;labelCache.set(key,w);}\n  return w;\n}\nfunction drawSpaced(text,x,y,font,sp){\n  const w=spacedWidth(text,font,sp);ctx.font=font;let cx=x-w.total/2;let i=0;\n  for(const ch of text){ctx.fillText(ch,cx,y);cx+=w[i++]+sp;}\n  return w.total;\n}\nfunction strokePoly(pts){\n  let pen=false;ctx.beginPath();\n  for(let k=0;k<pts.length;k+=3){\n    if(proj(pts[k],pts[k+1],pts[k+2])&&PD>-0.15){if(pen)ctx.lineTo(PX,PY);else{ctx.moveTo(PX,PY);pen=true;}}\n    else pen=false;\n  }\n  ctx.stroke();\n}\n\n/* ---------- main draw ---------- */\nfunction draw(now){\n  setView();\n  ctx.setTransform(DPR,0,0,DPR,0,0);\n  ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;\n  ctx.drawImage(bgCanvas,0,0,W,H);\n\n  // milky way\n  ctx.globalCompositeOperation='lighter';\n  for(let i=0;i<NMW;i++){\n    if(!proj(MX[i],MY[i],MZ[i])||PD<-0.1) continue;\n    const s=MS[i]*SZSCALE*(1.2/(0.2+PD*0.5+0.5));\n    if(!onScreen(s)) continue;\n    ctx.globalAlpha=MA[i];\n    ctx.drawImage(MWSPR[MT[i]],PX-s/2,PY-s/2,s,s);\n  }\n  ctx.fillStyle='#e3e8ff';\n  for(let i=0;i<NDU;i++){\n    if(!proj(DX[i],DY[i],DZ[i])||!onScreen(2)) continue;\n    ctx.globalAlpha=DA[i]*0.85;ctx.fillRect(PX,PY,1,1);\n  }\n  ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;\n\n  if(showGrid) drawGrid();\n\n  // star positions (for picking + lines)\n  for(let i=0;i<NS;i++){\n    if(proj(SX[i],SY[i],SZ[i])&&onScreen(30)){SPX[i]=PX;SPY[i]=PY;SVIS[i]=1;}else SVIS[i]=0;\n  }\n\n  const hot=listHover!==null?listHover:canvasHover;\n  for(const c of cons) drawHalo(c,now,hot);\n  for(const c of cons) drawLines(c,now,hot);\n  drawStars(now);\n  if(chain) drawChain(now);\n  placed.length=0;\n  for(const c of cons) drawLabel(c,now,hot);\n  drawHoverStar(now);\n  drawMeteor(now);\n}\n\nfunction drawGrid(){\n  ctx.lineWidth=0.7;\n  for(const p of PAR){ctx.strokeStyle=p.dec===0?'rgba(232,200,114,0.42)':'rgba(232,200,114,0.17)';if(p.dec===0)ctx.lineWidth=1;else ctx.lineWidth=0.7;strokePoly(p.pts);}\n  ctx.lineWidth=0.7;\n  for(const m of MER){ctx.strokeStyle=m.h%6===0?'rgba(232,200,114,0.3)':'rgba(232,200,114,0.15)';strokePoly(m.pts);}\n  ctx.setLineDash([6,5]);ctx.strokeStyle='rgba(240,170,120,0.45)';ctx.lineWidth=0.9;strokePoly(ECLP);ctx.setLineDash([]);\n  // labels\n  ctx.fillStyle='rgba(232,200,114,0.75)';ctx.textAlign='center';ctx.textBaseline='middle';\n  ctx.font='11px '+SERIF;\n  for(let h=0;h<24;h++){const v=radec(h*15*D2R,0);if(proj(v[0],v[1],v[2])&&PD>0&&onScreen(-20)){ctx.fillText(h+'ʰ',PX,PY-9);}}\n  ctx.font='italic 11px '+SERIF;\n  for(const hr of [0,6,12,18]){\n    for(let d=-60;d<=75;d+=15){if(d===0)continue;const v=radec((hr*15+3)*D2R,d*D2R);if(proj(v[0],v[1],v[2])&&PD>0.05&&onScreen(-20))ctx.fillText((d>0?'+':'−')+Math.abs(d)+'°',PX,PY-8);}\n  }\n  // equator + ecliptic names, placed near the chart centre\n  let best=-1,bd=1e9,bx=0,by=0;\n  for(let k=0;k<ECLP.length;k+=3){if(proj(ECLP[k],ECLP[k+1],ECLP[k+2])&&PD>0.2){const dd=Math.hypot(PX-CX*0.8,PY-CY*1.2);if(dd<bd){bd=dd;best=k;bx=PX;by=PY;}}}\n  if(best>=0){ctx.fillStyle='rgba(240,180,130,0.8)';ctx.font='italic 12.5px '+SERIF;ctx.fillText('Ecliptica',bx,by+13);}\n  if(proj(0,0,1)&&onScreen(-10)){\n    ctx.strokeStyle='rgba(232,200,114,0.7)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(PX-8,PY);ctx.lineTo(PX+8,PY);ctx.moveTo(PX,PY-8);ctx.lineTo(PX,PY+8);ctx.stroke();\n    ctx.beginPath();ctx.arc(PX,PY,4,0,TAU);ctx.stroke();\n    ctx.fillStyle='rgba(232,200,114,0.85)';ctx.font='10px '+SERIF;drawSpaced('POLUS BOREALIS',PX,PY+20,'10px '+SERIF,2.6);\n  }\n  if(proj(0,0,-1)&&onScreen(-10)){\n    ctx.fillStyle='rgba(232,200,114,0.85)';drawSpaced('POLUS AUSTRALIS',PX,PY+16,'10px '+SERIF,2.6);\n  }\n}\n\nfunction drawStars(now){\n  const amp=reduced?0.08:0.32;\n  for(let i=0;i<NS;i++){\n    if(!SVIS[i]) continue;\n    const x=SPX[i],y=SPY[i];\n    const tw=1-amp*(0.5+0.5*Math.sin(now*FQ[i]+PH[i]))*(MAG[i]>3?1:0.55);\n    const r=RAD[i]*(0.85+0.3*SZSCALE);\n    const a=ALP[i]*tw;\n    if(MAG[i]<3.4){\n      const gs=r*(MAG[i]<1.5?11:8);\n      ctx.globalAlpha=a*0.55;ctx.drawImage(GLOW[TB[i]],x-gs/2,y-gs/2,gs,gs);\n    }\n    ctx.globalAlpha=a;ctx.fillStyle=COL[i];\n    if(r<1.1){ctx.fillRect(x-r,y-r,r*2,r*2);}\n    else{ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fill();}\n    if(MAG[i]<1.2){\n      const L=r*6*tw;ctx.globalAlpha=0.35*tw;ctx.strokeStyle=COL[i];ctx.lineWidth=0.7;\n      ctx.beginPath();ctx.moveTo(x-L,y);ctx.lineTo(x+L,y);ctx.moveTo(x,y-L);ctx.lineTo(x,y+L);ctx.stroke();\n    }\n  }\n  ctx.globalAlpha=1;\n}\n\nconst placed=[];\nfunction labelHits(x,y,hw,hh){for(const r of placed){if(Math.abs(x-r.x)<hw+r.hw-30&&Math.abs(y-r.y)<hh+r.hh)return true;}return false;}\nfunction consAlpha(c,hot){return hot===null?1:(hot===c.id?1:0.3);}\nfunction reveal(c,now){if(reduced)return 1;return Math.min(1,Math.max(0,(now-c.born)/1600));}\n/* halo = the convex hull of the figure, grown by a radius (a rounded \"cloud\" as on old atlas plates) */\nconst HX=new Float32Array(1200),HY=new Float32Array(1200);let HN=0;\nfunction crossO(o,a,b){return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);}\nfunction convexHull(p){\n  p.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);\n  if(p.length<3)return p.slice();\n  const lo=[],up=[];\n  for(const q of p){while(lo.length>=2&&crossO(lo[lo.length-2],lo[lo.length-1],q)<=0)lo.pop();lo.push(q);}\n  for(let i=p.length-1;i>=0;i--){const q=p[i];while(up.length>=2&&crossO(up[up.length-2],up[up.length-1],q)<=0)up.pop();up.push(q);}\n  lo.pop();up.pop();return lo.concat(up);\n}\nfunction geom(c){\n  let sx=0,sy=0,n=0;const pts=[];\n  for(const s of c.stars){if(!SVIS[s])continue;sx+=SPX[s];sy+=SPY[s];n++;pts.push([SPX[s],SPY[s]]);}\n  if(n<2) return null;\n  return {cx:sx/n,cy:sy/n,n,pts};\n}\nfunction haloShape(g,pad){\n  const h=convexHull(g.pts);HN=0;\n  const m=h.length;\n  if(m===1){for(let k=0;k<48;k++){const a=k/48*TAU;HX[HN]=h[0][0]+Math.cos(a)*pad;HY[HN]=h[0][1]+Math.sin(a)*pad;HN++;}return;}\n  for(let i=0;i<m;i++){\n    const p=h[(i+m-1)%m],v=h[i],q=h[(i+1)%m];\n    const a1=Math.atan2(-(v[0]-p[0]),(v[1]-p[1])); // outward normal of incoming edge (dy,-dx)\n    const a2=Math.atan2(-(q[0]-v[0]),(q[1]-v[1]));\n    let da=a2-a1;while(da<0)da+=TAU;while(da>=TAU)da-=TAU;\n    const steps=Math.max(1,Math.ceil(da/(TAU/40)));\n    for(let k=0;k<=steps&&HN<1190;k++){const a=a1+da*k/steps;HX[HN]=v[0]+Math.cos(a)*pad;HY[HN]=v[1]+Math.sin(a)*pad;HN++;}\n  }\n}\nfunction drawHalo(c,now,hot){\n  const g=geom(c);c._g=g;if(!g)return;\n  const rv=reveal(c,now),ea=consAlpha(c,hot)*rv;\n  const lit=hot===c.id;\n  const pad=(22+6*SZSCALE)*(0.55+0.45*rv);\n  haloShape(g,pad);\n  let maxR=0,top=1e9,bot=-1e9;\n  for(let k=0;k<HN;k++){const d=Math.hypot(HX[k]-g.cx,HY[k]-g.cy);if(d>maxR)maxR=d;if(HY[k]<top)top=HY[k];if(HY[k]>bot)bot=HY[k];}\n  c._r=maxR;c._top=top;c._bot=bot;\n  // soft wash\n  const grd=ctx.createRadialGradient(g.cx,g.cy,0,g.cx,g.cy,maxR*1.02);\n  grd.addColorStop(0,'rgba(232,200,114,'+(lit?0.12:0.05)*ea+')');grd.addColorStop(0.75,'rgba(232,200,114,'+(lit?0.07:0.03)*ea+')');grd.addColorStop(1,'rgba(232,200,114,0.01)');\n  ctx.fillStyle=grd;\n  ctx.beginPath();ctx.moveTo(HX[0],HY[0]);for(let k=1;k<HN;k++)ctx.lineTo(HX[k],HY[k]);ctx.closePath();\n  ctx.fill();\n  // engraved dotted outline\n  ctx.strokeStyle='rgba(232,200,114,'+(lit?0.75:0.42)*ea+')';ctx.lineWidth=0.8;ctx.setLineDash([1.2,3.4]);ctx.stroke();ctx.setLineDash([]);\n  // burin hatching: evenly spaced strokes along the outline, lengths breathing like a slow shimmer\n  ctx.strokeStyle='rgba(232,200,114,'+(lit?0.55:0.26)*ea+')';ctx.lineWidth=0.6;ctx.beginPath();\n  const step=5.5;let acc=0,sIdx=0;\n  for(let k=0;k<HN;k++){\n    const x0=HX[k],y0=HY[k],x1=HX[(k+1)%HN],y1=HY[(k+1)%HN];\n    const dx=x1-x0,dy=y1-y0,L=Math.hypot(dx,dy);if(L<1e-3)continue;\n    const nx=dy/L,ny=-dx/L;\n    let t=acc;\n    while(t<L){\n      const px=x0+dx*t/L,py=y0+dy*t/L;\n      const wave=reduced?0.5:0.5+0.5*Math.sin(sIdx*0.45-now*0.0016+c.id);\n      const len=(sIdx%4===0?4.5:2.2)+wave*3.2;\n      ctx.moveTo(px+nx*2.5,py+ny*2.5);ctx.lineTo(px+nx*(2.5+len),py+ny*(2.5+len));\n      t+=step;sIdx++;\n    }\n    acc=t-L;\n  }\n  ctx.stroke();\n}\nfunction edgeSeg(a,b,gapA,gapB){\n  const dx=SPX[b]-SPX[a],dy=SPY[b]-SPY[a],L=Math.hypot(dx,dy);if(L<gapA+gapB+2)return null;\n  const ux=dx/L,uy=dy/L;return [SPX[a]+ux*gapA,SPY[a]+uy*gapA,SPX[b]-ux*gapB,SPY[b]-uy*gapB];\n}\nfunction starGap(s){return RAD[s]*(0.85+0.3*SZSCALE)+4.5;}\nfunction drawLines(c,now,hot){\n  const ea=consAlpha(c,hot);const lit=hot===c.id;\n  const rv=reveal(c,now);const ne=c.edges.length;\n  ctx.lineCap='round';\n  for(let e=0;e<ne;e++){\n    const f=Math.min(1,Math.max(0,rv*ne*1.15-e));if(f<=0)break;\n    const [a,b]=c.edges[e];if(!SVIS[a]||!SVIS[b])continue;\n    const seg=edgeSeg(a,b,starGap(a),starGap(b));if(!seg)continue;\n    const x2=seg[0]+(seg[2]-seg[0])*f,y2=seg[1]+(seg[3]-seg[1])*f;\n    ctx.strokeStyle='rgba(232,200,114,'+(lit?0.28:0.12)*ea+')';ctx.lineWidth=lit?6:4;\n    ctx.beginPath();ctx.moveTo(seg[0],seg[1]);ctx.lineTo(x2,y2);ctx.stroke();\n    ctx.strokeStyle=lit?'rgba(250,230,170,'+ea+')':'rgba(232,200,114,'+0.88*ea+')';ctx.lineWidth=lit?1.6:1.15;\n    ctx.beginPath();ctx.moveTo(seg[0],seg[1]);ctx.lineTo(x2,y2);ctx.stroke();\n  }\n  // tiny gold rings around member stars\n  ctx.strokeStyle='rgba(232,200,114,'+0.55*ea*rv+')';ctx.lineWidth=0.7;\n  for(const s of c.stars){if(!SVIS[s])continue;ctx.beginPath();ctx.arc(SPX[s],SPY[s],starGap(s)-1.5,0,TAU);ctx.stroke();}\n}\nfunction drawLabel(c,now,hot){\n  const g=c._g;if(!g||!c._r)return;\n  if(g.cx<0||g.cx>W||g.cy<0||g.cy>H)return; // figure mostly off the plate: no cartouche\n  const rv=reveal(c,now);const la=Math.max(0,Math.min(1,(rv-0.45)/0.55));if(la<=0)return;\n  const ea=consAlpha(c,hot)*la;const lit=hot===c.id;\n  const fs=Math.round(Math.max(11,Math.min(15,12*SZSCALE+2)));\n  const mobile=W<760;\n  const sp=fs*0.34*(1+(1-la)*0.8);\n  const name=c.name.toUpperCase();\n  const font=fs+'px '+SERIF;\n  // keep the cartouche clear of the toolbar and the catalogue panel\n  const floorY=H-(mobile?182:168);\n  const half=spacedWidth(name,font,sp).total/2+44;\n  const rightEdge=W-(mobile?12:(W<=980?300:340)+56);\n  let x=g.cx;\n  if(rightEdge-12>2*half)x=Math.min(rightEdge-half,Math.max(12+half,x));\n  // choose a baseline below (or above) the halo that does not collide with labels already set this frame\n  const hh=fs+9,minY=fs+24,maxY=floorY-fs-8;\n  const below=c._bot+fs+8,above=c._top-fs-14,stepY=2*hh+4;\n  const tries=[below,above,below+stepY,above-stepY,below+2*stepY,above-2*stepY];\n  let y=null;\n  for(const ty of tries){if(ty<minY||ty>maxY)continue;if(!labelHits(x,ty+fs*0.45,half,hh)){y=ty;break;}}\n  if(y===null)y=Math.max(minY,Math.min(maxY,below));\n  placed.push({x,y:y+fs*0.45,hw:half,hh});\n  ctx.textAlign='left';ctx.textBaseline='alphabetic';\n  // shadow plate for legibility\n  ctx.shadowColor='rgba(4,6,20,0.95)';ctx.shadowBlur=8;\n  ctx.fillStyle=lit?'rgba(255,238,190,'+ea+')':'rgba(240,222,170,'+0.92*ea+')';\n  const tw=drawSpaced(name,x,y,font,sp);\n  ctx.shadowBlur=0;\n  // flourishes\n  ctx.strokeStyle='rgba(232,200,114,'+0.6*ea+')';ctx.lineWidth=0.8;ctx.beginPath();\n  const fx=tw/2+12;ctx.moveTo(x-fx-26,y-fs*0.33);ctx.lineTo(x-fx,y-fs*0.33);ctx.moveTo(x+fx,y-fs*0.33);ctx.lineTo(x+fx+26,y-fs*0.33);ctx.stroke();\n  ctx.fillStyle='rgba(232,200,114,'+0.8*ea+')';\n  for(const sx of [-fx-3,fx+3]){ctx.beginPath();const cy=y-fs*0.33;ctx.moveTo(x+sx-3,cy);ctx.lineTo(x+sx,cy-3);ctx.lineTo(x+sx+3,cy);ctx.lineTo(x+sx,cy+3);ctx.closePath();ctx.fill();}\n  // latin subtitle\n  ctx.fillStyle='rgba(200,198,222,'+0.85*ea+')';ctx.textAlign='center';ctx.shadowBlur=6;\n  ctx.font='italic '+(fs+1)+'px '+SERIF;ctx.fillText(c.latin,x,y+fs+6);\n  ctx.shadowBlur=0;ctx.shadowColor='transparent';\n}\nfunction drawChain(now){\n  const pulse=reduced?0.8:0.65+0.35*Math.sin(now*0.006);\n  ctx.lineCap='round';\n  for(const [a,b] of chain.edges){\n    if(!SVIS[a]||!SVIS[b])continue;const seg=edgeSeg(a,b,starGap(a),starGap(b));if(!seg)continue;\n    ctx.strokeStyle='rgba(232,200,114,0.18)';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(seg[0],seg[1]);ctx.lineTo(seg[2],seg[3]);ctx.stroke();\n    ctx.strokeStyle='rgba(246,227,168,'+pulse+')';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(seg[0],seg[1]);ctx.lineTo(seg[2],seg[3]);ctx.stroke();\n  }\n  for(let k=0;k<chain.stars.length;k++){\n    const s=chain.stars[k];if(!SVIS[s])continue;\n    ctx.strokeStyle=k===0?'rgba(246,227,168,0.95)':'rgba(232,200,114,0.7)';ctx.lineWidth=k===0?1.2:0.9;\n    ctx.beginPath();ctx.arc(SPX[s],SPY[s],starGap(s)+(k===0?3:0),0,TAU);ctx.stroke();\n    if(k===0&&chain.edges.length>=2){ctx.setLineDash([2,3]);ctx.beginPath();ctx.arc(SPX[s],SPY[s],starGap(s)+8+2*Math.sin(now*0.005),0,TAU);ctx.stroke();ctx.setLineDash([]);}\n  }\n  const l=chain.last;\n  if(SVIS[l]&&pointer.in&&!drag.moving){\n    const tx=hoverStar>=0?SPX[hoverStar]:pointer.x,ty=hoverStar>=0?SPY[hoverStar]:pointer.y;\n    const dx=tx-SPX[l],dy=ty-SPY[l],L=Math.hypot(dx,dy);\n    if(L>starGap(l)+4){\n      const g0=starGap(l);ctx.setLineDash([3,6]);ctx.lineDashOffset=reduced?0:-now*0.02;\n      ctx.strokeStyle='rgba(232,200,114,0.55)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(SPX[l]+dx/L*g0,SPY[l]+dy/L*g0);ctx.lineTo(tx-(hoverStar>=0?dx/L*starGap(hoverStar):0),ty-(hoverStar>=0?dy/L*starGap(hoverStar):0));ctx.stroke();\n      ctx.setLineDash([]);ctx.lineDashOffset=0;\n    }\n  }\n}\nfunction drawHoverStar(now){\n  if(hoverStar<0||!SVIS[hoverStar]||drag.moving)return;\n  const x=SPX[hoverStar],y=SPY[hoverStar],r=starGap(hoverStar)+5;\n  const rot=reduced?0:now*0.0012;\n  ctx.strokeStyle='rgba(246,227,168,0.9)';ctx.lineWidth=0.9;\n  ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.stroke();\n  ctx.beginPath();\n  for(let k=0;k<4;k++){const a=rot+k*Math.PI/2;ctx.moveTo(x+Math.cos(a)*(r+2),y+Math.sin(a)*(r+2));ctx.lineTo(x+Math.cos(a)*(r+7),y+Math.sin(a)*(r+7));}\n  ctx.stroke();\n  ctx.fillStyle='rgba(225,222,240,0.9)';ctx.font='italic 12px '+SERIF;ctx.textAlign='left';ctx.textBaseline='middle';\n  ctx.shadowColor='rgba(4,6,20,.95)';ctx.shadowBlur=6;\n  ctx.fillText('Stella '+(1000+hoverStar)+' · mag '+MAG[hoverStar].toFixed(1),x+r+12,y-10);\n  ctx.shadowBlur=0;ctx.shadowColor='transparent';\n}\nfunction drawMeteor(now){\n  if(reduced)return;\n  if(!meteor&&now>nextMeteor){\n    const a=(20+Math.random()*40)*D2R*(Math.random()<.5?1:-1)+Math.PI/2*0.2;\n    meteor={x:W*(0.1+Math.random()*0.6),y:H*(0.08+Math.random()*0.4),a:Math.PI*0.15+Math.random()*0.35,t0:now,len:120+Math.random()*120,sp:0.9+Math.random()*0.5};\n    nextMeteor=now+9000+Math.random()*14000;\n  }\n  if(!meteor)return;\n  const t=(now-meteor.t0)/900;if(t>1){meteor=null;return;}\n  const d=t*meteor.len*3*meteor.sp;const hx=meteor.x+Math.cos(meteor.a)*d,hy=meteor.y+Math.sin(meteor.a)*d;\n  const tx=hx-Math.cos(meteor.a)*meteor.len*(1-t*0.5),ty=hy-Math.sin(meteor.a)*meteor.len*(1-t*0.5);\n  const g=ctx.createLinearGradient(tx,ty,hx,hy);const fa=Math.sin(t*Math.PI);\n  g.addColorStop(0,'rgba(255,245,220,0)');g.addColorStop(1,'rgba(255,245,220,'+0.8*fa+')');\n  ctx.strokeStyle=g;ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(tx,ty);ctx.lineTo(hx,hy);ctx.stroke();\n}\n\n/* ---------- picking ---------- */\nfunction pickStar(x,y,touch){\n  const R=touch?30:20;let best=-1,bs=1e9;\n  for(let i=0;i<NS;i++){\n    if(!SVIS[i]||MAG[i]>6.1)continue;\n    const dx=SPX[i]-x,dy=SPY[i]-y;if(Math.abs(dx)>R||Math.abs(dy)>R)continue;\n    const d=Math.hypot(dx,dy);if(d>R)continue;\n    const sc=d-(6.6-MAG[i])*2.2;if(sc<bs){bs=sc;best=i;}\n  }\n  return best;\n}\nfunction pickCons(x,y){\n  let best=null,bd=1e9;\n  for(const c of cons){const g=c._g;if(!g||!c._r)continue;const d=Math.hypot(x-g.cx,y-g.cy);if(d<c._r*0.9&&d<bd){bd=d;best=c.id;}}\n  return best;\n}\n\n/* ---------- chain logic ---------- */\nconst hintEl=document.getElementById('hint');\nfunction hint(k,t){hintEl.innerHTML='';const s=document.createElement('span');s.className='k';s.textContent=k;hintEl.append(s,document.createTextNode(t));}\nfunction chainHint(){\n  if(!chain){hint('Begin','Select a star to start a figure');return;}\n  const n=chain.stars.length,e=chain.edges.length;\n  if(e===0)hint('One star','Now select another to draw the first line');\n  else if(e===1)hint(n+' stars','Keep linking — or press Name it');\n  else hint(n+' stars · '+e+' lines','Return to the first star to close the figure, or press Name it');\n}\nfunction hasEdge(E,a,b){return E.some(x=>(x[0]===a&&x[1]===b)||(x[0]===b&&x[1]===a));}\nfunction handleStar(i){\n  if(!chain){chain={stars:[i],edges:[],last:i};chainHint();return;}\n  if(i===chain.last)return;\n  const a=chain.last;\n  if(!hasEdge(chain.edges,a,i))chain.edges.push([a,i]);\n  if(i===chain.stars[0]&&chain.edges.length>=2){finalize(true);return;}\n  if(!chain.stars.includes(i))chain.stars.push(i);\n  chain.last=i;chainHint();\n}\nfunction finalize(closed){\n  if(!chain||chain.edges.length<1){hint('Not yet','Link at least two stars before naming a figure');return;}\n  const nm=makeName();\n  const c={id:nextId++,stars:chain.stars.slice(),edges:chain.edges.map(e=>e.slice()),name:nm.name,latin:nm.latin,made:new Date().toISOString().slice(0,10),born:performance.now()};\n  cons.push(c);chain=null;save();renderList(c.id);\n  toast(nm.name,nm.latin+(closed?' — the figure is closed and set among the stars':' — set among the stars'));\n  hint('Named',c.name+' now keeps its place in your sky');\n  setTimeout(()=>{if(!chain)chainHint();},4200);\n}\nfunction undo(){\n  if(chain){\n    if(chain.edges.length===0){chain=null;chainHint();return;}\n    chain.edges.pop();\n    const used=new Set([chain.stars[0]]);for(const [a,b] of chain.edges){used.add(a);used.add(b);}\n    chain.stars=chain.stars.filter(s=>used.has(s));\n    const le=chain.edges[chain.edges.length-1];chain.last=le?le[1]:chain.stars[0];\n    chainHint();return;\n  }\n  if(cons.length){const c=cons.pop();save();renderList();toast('Unmade',c.name+' returns to the unnamed stars');}\n}\n\n/* ---------- panel list ---------- */\nconst listEl=document.getElementById('list'),emptyEl=document.getElementById('empty'),badge=document.getElementById('countBadge');\nfunction renderList(freshId){\n  listEl.innerHTML='';\n  cons.forEach((c,idx)=>{\n    const li=document.createElement('li');li.className='entry'+(c.id===freshId?' fresh':'');li.dataset.id=c.id;\n    const b=document.createElement('button');b.type='button';b.className='entry-main';b.setAttribute('aria-label','Turn the sky to '+c.name+', '+c.latin);\n    const num=document.createElement('span');num.className='num';num.textContent=toRoman(idx+1);\n    const names=document.createElement('span');names.className='names';\n    const nm=document.createElement('span');nm.className='nm';nm.textContent=c.name;\n    const lt=document.createElement('span');lt.className='lat';lt.textContent=c.latin;\n    names.append(nm,lt);\n    const meta=document.createElement('span');meta.className='meta';meta.textContent=c.stars.length+' ✶';\n    b.append(num,names,meta);\n    const del=document.createElement('button');del.type='button';del.className='entry-del';del.setAttribute('aria-label','Remove '+c.name);\n    del.innerHTML='<svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M1.5 1.5l9 9M10.5 1.5l-9 9\" stroke=\"currentColor\" stroke-width=\"1.3\"/></svg>';\n    li.append(b,del);\n    const on=()=>{listHover=c.id;syncHot();},off=()=>{if(listHover===c.id){listHover=null;syncHot();}};\n    li.addEventListener('pointerenter',on);li.addEventListener('pointerleave',off);\n    b.addEventListener('focus',on);b.addEventListener('blur',off);\n    b.addEventListener('click',()=>flyTo(c));\n    del.addEventListener('click',()=>{cons=cons.filter(x=>x.id!==c.id);if(listHover===c.id)listHover=null;save();renderList();toast('Erased',c.name+' has been scraped from the plate');});\n    listEl.append(li);\n  });\n  emptyEl.hidden=cons.length>0;badge.textContent=cons.length;\n}\nfunction syncHot(){\n  const hot=listHover!==null?listHover:canvasHover;\n  for(const li of listEl.children){li.classList.toggle('hot',Number(li.dataset.id)===hot);}\n}\nfunction flyTo(c){\n  let v=[0,0,0];for(const s of c.stars){v[0]+=SX[s];v[1]+=SY[s];v[2]+=SZ[s];}v=norm(v);\n  const ra=Math.atan2(v[1],v[0]),dec=Math.asin(Math.max(-1,Math.min(1,v[2])));\n  let dra=ra-view.ra;dra=((dra%TAU)+TAU*1.5)%TAU-Math.PI;\n  const mobile=W<760;\n  fly={ra0:view.ra,dec0:view.dec,dra,ddec:Math.max(-75*D2R,Math.min(82*D2R,dec+(mobile?0.05:0)))-view.dec,t0:performance.now(),dur:reduced?1:1400};\n  view.vra=view.vdec=0;\n  if(mobile)setPanel(false);\n}\n\n/* ---------- toast ---------- */\nconst toastEl=document.getElementById('toast');let toastTimer=0;\nfunction toast(a,b){document.getElementById('toastT1').textContent=a;document.getElementById('toastT2').textContent=b;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),3600);}\n\n/* ---------- pointer ---------- */\nfunction localXY(e){const r=canvas.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];}\ncanvas.addEventListener('pointerdown',e=>{\n  if(e.button!==undefined&&e.button!==0)return;\n  const [x,y]=localXY(e);\n  drag.down=true;drag.moving=false;drag.x0=drag.lx=x;drag.y0=drag.ly=y;drag.id=e.pointerId;drag.t=performance.now();drag.type=e.pointerType;\n  pointer.x=x;pointer.y=y;pointer.in=true;\n  try{canvas.setPointerCapture(e.pointerId);}catch(err){}\n  fly=null;view.vra=view.vdec=0;\n});\ncanvas.addEventListener('pointermove',e=>{\n  const [x,y]=localXY(e);pointer.x=x;pointer.y=y;pointer.in=true;\n  if(drag.down&&e.pointerId===drag.id){\n    const th=drag.type==='touch'?10:6;\n    if(!drag.moving&&Math.hypot(x-drag.x0,y-drag.y0)>th){drag.moving=true;canvas.classList.add('grabbing');}\n    if(drag.moving){\n      const dx=x-drag.lx,dy=y-drag.ly;drag.lx=x;drag.ly=y;\n      const kra=1/(SC*Math.max(0.35,Math.cos(view.dec)));\n      view.ra+=dx*kra;view.dec=Math.max(-75*D2R,Math.min(82*D2R,view.dec+dy/SC));\n      view.vra=dx*kra*60;view.vdec=dy/SC*60;\n    }\n  }\n  if(!drag.moving&&e.pointerType!=='touch'){\n    hoverStar=pickStar(x,y,false);\n    const hc=hoverStar<0&&!chain?pickCons(x,y):null;\n    if(hc!==canvasHover){canvasHover=hc;syncHot();}\n    canvas.classList.toggle('over-star',hoverStar>=0);\n  }\n});\nfunction endDrag(e){\n  if(!drag.down||e.pointerId!==drag.id)return;\n  const [x,y]=localXY(e);\n  if(!drag.moving){\n    const s=pickStar(x,y,drag.type==='touch');\n    if(s>=0)handleStar(s);\n    else if(chain)hint('No star there','Choose a star close to your cursor — or press Esc to set the figure aside');\n  }\n  drag.down=false;drag.moving=false;canvas.classList.remove('grabbing');\n  if(e.pointerType==='touch'){pointer.in=false;hoverStar=-1;}\n}\ncanvas.addEventListener('pointerup',endDrag);\ncanvas.addEventListener('pointercancel',e=>{drag.down=false;drag.moving=false;canvas.classList.remove('grabbing');});\ncanvas.addEventListener('pointerleave',e=>{if(!drag.down){pointer.in=false;hoverStar=-1;if(canvasHover!==null){canvasHover=null;syncHot();}}});\ncanvas.addEventListener('wheel',e=>{\n  e.preventDefault();\n  view.zoom=Math.max(0.7,Math.min(2.4,view.zoom*Math.exp(-e.deltaY*0.0012)));\n  resize();\n},{passive:false});\n\n/* ---------- keyboard ---------- */\nwindow.addEventListener('keydown',e=>{\n  const tag=(e.target&&e.target.tagName)||'';\n  if(tag==='INPUT'||tag==='TEXTAREA')return;\n  const onCanvas=e.target===canvas||e.target===document.body;\n  if(e.key==='Enter'&&onCanvas){e.preventDefault();finalize(false);}\n  else if(e.key==='Escape'){if(chain){chain=null;chainHint();}if(W<760)setPanel(false);}\n  else if((e.key==='Backspace'&&onCanvas)||((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z')){e.preventDefault();undo();}\n  else if(e.key.toLowerCase()==='g'&&!e.ctrlKey&&!e.metaKey){toggleGrid();}\n  else if(onCanvas&&e.key.startsWith('Arrow')){\n    e.preventDefault();fly=null;const st=3*D2R;\n    if(e.key==='ArrowLeft')view.ra-=st/Math.max(.35,Math.cos(view.dec));\n    if(e.key==='ArrowRight')view.ra+=st/Math.max(.35,Math.cos(view.dec));\n    if(e.key==='ArrowUp')view.dec=Math.min(82*D2R,view.dec+st);\n    if(e.key==='ArrowDown')view.dec=Math.max(-75*D2R,view.dec-st);\n  }\n});\n\n/* ---------- buttons ---------- */\nconst btnGrid=document.getElementById('btnGrid'),btnSpin=document.getElementById('btnSpin'),btnClear=document.getElementById('btnClear');\nfunction toggleGrid(){showGrid=!showGrid;btnGrid.setAttribute('aria-pressed',String(showGrid));save();}\nbtnGrid.addEventListener('click',toggleGrid);\nbtnSpin.addEventListener('click',()=>{spin=!spin;btnSpin.setAttribute('aria-pressed',String(spin));updateMode();});\ndocument.getElementById('btnName').addEventListener('click',()=>finalize(false));\ndocument.getElementById('btnUndo').addEventListener('click',undo);\nlet clearArmed=0;\nbtnClear.addEventListener('click',()=>{\n  if(!clearArmed){\n    if(!cons.length&&!chain){toast('Already clear','There is nothing yet to scrape from the plate');return;}\n    clearArmed=setTimeout(()=>{clearArmed=0;btnClear.classList.remove('armed');document.getElementById('clearLabel').textContent='Clear sky';},3000);\n    btnClear.classList.add('armed');document.getElementById('clearLabel').textContent='Sure?';return;\n  }\n  clearTimeout(clearArmed);clearArmed=0;btnClear.classList.remove('armed');document.getElementById('clearLabel').textContent='Clear sky';\n  const n=cons.length;cons=[];chain=null;listHover=canvasHover=null;save();renderList();chainHint();\n  toast('A clean plate',n+' figure'+(n===1?'':'s')+' returned to the nameless dark');\n});\ndocument.getElementById('btnSave').addEventListener('click',savePNG);\nconst makeObj=URL.createObjectURL,dropObj=URL.revokeObjectURL;\nfunction savePNG(){\n  try{\n    const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;\n    const o=out.getContext('2d');o.drawImage(canvas,0,0);o.setTransform(DPR,0,0,DPR,0,0);\n    // engraved cartouche\n    const bx=34,by=H-128,bw=Math.min(360,W-68),bh=94;\n    o.fillStyle='rgba(6,8,24,0.78)';o.fillRect(bx,by,bw,bh);\n    o.strokeStyle='rgba(232,200,114,0.7)';o.lineWidth=1;o.strokeRect(bx+.5,by+.5,bw-1,bh-1);\n    o.strokeStyle='rgba(232,200,114,0.25)';o.strokeRect(bx+5.5,by+5.5,bw-11,bh-11);\n    o.fillStyle='#efe6cf';o.font='26px '+SERIF;o.textBaseline='alphabetic';\n    let x=bx+22;for(const ch of 'ASTERISM'){o.fillText(ch,x,by+42);x+=o.measureText(ch).width+8;}\n    o.fillStyle='#e8c872';o.font='italic 14px '+SERIF;\n    o.fillText('Tabula caeli nova · '+cons.length+' figure'+(cons.length===1?'':'s')+' · '+new Date().toISOString().slice(0,10),bx+22,by+68);\n    out.toBlob(b=>{\n      if(!b){toast('Could not save','This browser refused to export the chart');return;}\n      const u=makeObj.call(URL,b);const a=document.createElement('a');a.href=u;a.download='asterism-sky.png';document.body.appendChild(a);a.click();a.remove();\n      setTimeout(()=>dropObj.call(URL,u),5000);toast('Plate printed','Your chart was saved as asterism-sky.png');\n    },'image/png');\n  }catch(err){toast('Could not save','This browser refused to export the chart');}\n}\n\n/* ---------- mobile panel ---------- */\nconst panel=document.getElementById('panel'),ptog=document.getElementById('panelToggle');\nfunction setPanel(open){panel.classList.toggle('open',open);ptog.setAttribute('aria-expanded',String(open));}\nptog.addEventListener('click',()=>setPanel(!panel.classList.contains('open')));\n\n/* ---------- readout ---------- */\nconst roRA=document.getElementById('roRA'),roDec=document.getElementById('roDec'),roMode=document.getElementById('roMode');\nfunction updateMode(){roMode.textContent=reduced?'Still sky · reduced motion':(spin?'The sky turns slowly westward':'The sky is held still');}\nlet lastRO=0;\nfunction updateReadout(now){\n  if(now-lastRO<150)return;lastRO=now;\n  let ra=(view.ra/D2R)%360;if(ra<0)ra+=360;const hrs=ra/15;const h=Math.floor(hrs),m=Math.floor((hrs-h)*60);\n  roRA.textContent=String(h).padStart(2,'0')+'ʰ '+String(m).padStart(2,'0')+'ᵐ';\n  const d=view.dec/D2R;roDec.textContent=(d>=0?'+':'−')+Math.abs(d).toFixed(0)+'°';\n}\n\n/* ---------- example figures on a first visit ---------- */\nfunction seedExamples(){\n  setView();\n  for(let i=0;i<NS;i++){if(proj(SX[i],SY[i],SZ[i])&&onScreen(0)){SPX[i]=PX;SPY[i]=PY;SVIS[i]=1;}else SVIS[i]=0;}\n  const mobile=W<760;\n  const targets=mobile?[[0.3,0.4,'Weeping','Heron'],[0.7,0.6,'Sleeping','Ferryman']]\n    :[[0.18,0.6,'Weeping','Heron'],[0.44,0.3,'Sleeping','Ferryman'],[0.61,0.6,'Watchful','Lantern']];\n  const taken=new Set();\n  for(const t of targets){\n    const tx=t[0]*W,ty=t[1]*H;const R=Math.min(W,H)*(mobile?0.17:0.15);\n    const cand=[];\n    for(let i=0;i<NS;i++){if(!SVIS[i]||MAG[i]>4.4||taken.has(i))continue;const d=Math.hypot(SPX[i]-tx,SPY[i]-ty);if(d<R)cand.push([i,d]);}\n    cand.sort((a,b)=>MAG[a[0]]-MAG[b[0]]);\n    const pick=cand.slice(0,mobile?5:6).map(c=>c[0]);\n    if(pick.length<3)continue;\n    // greedy nearest-neighbour path from the brightest\n    const path=[pick[0]];const rest=pick.slice(1);\n    while(rest.length){const l=path[path.length-1];let bi=0,bd=1e9;rest.forEach((s,k)=>{const d=Math.hypot(SPX[s]-SPX[l],SPY[s]-SPY[l]);if(d<bd){bd=d;bi=k;}});path.push(rest.splice(bi,1)[0]);}\n    const edges=[];for(let k=1;k<path.length;k++)edges.push([path[k-1],path[k]]);\n    if(path.length>=5)edges.push([path[path.length-1],path[1]]);\n    path.forEach(s=>taken.add(s));\n    const a=ADJ.find(x=>x[0]===t[2]),n=NOUN.find(x=>x[0]===t[3]);\n    cons.push({id:nextId++,stars:path,edges,name:'The '+a[0]+' '+n[0],latin:n[1]+' '+a[1],made:'2026-09-01',born:performance.now()+cons.length*450});\n  }\n  save();\n}\n\n/* ---------- loop ---------- */\nlet raf=0,lastT=performance.now();\nfunction frame(now){\n  raf=requestAnimationFrame(frame);\n  const dt=Math.min(0.05,(now-lastT)/1000);lastT=now;\n  if(fly){\n    const t=Math.min(1,(now-fly.t0)/fly.dur);const e=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;\n    view.ra=fly.ra0+fly.dra*e;view.dec=fly.dec0+fly.ddec*e;if(t>=1)fly=null;\n  }else if(!drag.down){\n    if(Math.abs(view.vra)>1e-5||Math.abs(view.vdec)>1e-5){\n      view.ra+=view.vra*dt;view.dec=Math.max(-75*D2R,Math.min(82*D2R,view.dec+view.vdec*dt));\n      const k=Math.exp(-dt*3.2);view.vra*=k;view.vdec*=k;\n    }\n    if(spin&&!reduced)view.ra+=dt*0.0075;\n  }\n  draw(now);\n  updateReadout(now);\n}\nfunction start(){if(!raf){lastT=performance.now();raf=requestAnimationFrame(frame);}}\nfunction stop(){if(raf){cancelAnimationFrame(raf);raf=0;}}\ndocument.addEventListener('visibilitychange',()=>{document.hidden?stop():start();});\nreduceMQ.addEventListener&&reduceMQ.addEventListener('change',e=>{reduced=e.matches;updateMode();});\nlet rzT=0;window.addEventListener('resize',()=>{clearTimeout(rzT);rzT=setTimeout(resize,60);resize();});\n\n/* ---------- boot ---------- */\nresize();\nconst had=load();\nif(!had)seedExamples();\nbtnGrid.setAttribute('aria-pressed',String(showGrid));\nrenderList();chainHint();updateMode();\nstart();\n})();\n</script>\n</body>\n</html>\n";
